def two_rank(letters):
    s = Svg(480, 320)
    xs = [120, 170, 220, 270, 320, 370]
    for x in xs: s.soldier(x, 140, 0); s.soldier(x, 190, 0)
    s.arrow(245, 70, 245, 30)
    # ширина: над строем от фланга до фланга
    s.line(107, 105, 383, 105, '#7a5c99', 2); s.line(107, 98, 107, 112, '#7a5c99', 2); s.line(383, 98, 383, 112, '#7a5c99', 2)
    # глубина: справа от строя
    s.line(410, 127, 410, 203, '#7a5c99', 2); s.line(403, 127, 417, 127, '#7a5c99', 2); s.line(403, 203, 417, 203, '#7a5c99', 2)
    # интервал: между 1 и 2 в первой шеренге (снизу)
    s.line(133, 236, 157, 236, '#7a5c99', 2); s.line(133, 230, 133, 242, '#7a5c99', 2); s.line(157, 230, 157, 242, '#7a5c99', 2); s.line(170, 203, 170, 222, '#bbb', 1, '3 3'); s.line(120, 203, 120, 222, '#bbb', 1, '3 3')
    # дистанция: слева, между шеренгами
    s.line(80, 153, 80, 177, '#7a5c99', 2); s.line(74, 153, 86, 153, '#7a5c99', 2); s.line(74, 177, 86, 177, '#7a5c99', 2)
    if letters:
        s.text(245, 96, 'А', 16, bold=True); s.text(432, 171, 'Б', 16, bold=True); s.text(145, 260, 'В', 16, bold=True); s.text(60, 171, 'Г', 16, bold=True)
    return s
