# --- 6. повороты на месте ---
DIRS = [0, 45, 90, 135, 180, 225, 270, 315]
DNAME = {0: 'вверх', 45: 'вверх-вправо', 90: 'вправо', 135: 'вниз-вправо', 180: 'вниз', 225: 'вниз-влево', 270: 'влево', 315: 'вверх-влево'}
def turn_svg(face):
    s = Svg(480, 320); cx, cy = 240, 160
    for a in DIRS:
        r = math.radians(a); x1, y1 = cx + 30 * math.sin(r), cy - 30 * math.cos(r); x2, y2 = cx + 92 * math.sin(r), cy - 92 * math.cos(r)
        s.arrow(round(x1, 1), round(y1, 1), round(x2, 1), round(y2, 1), '#8a8a8a', 2, 9)
    s.soldier(cx, cy, face, r=16)
    for a in DIRS:
        r = math.radians(a); zx, zy = cx + 118 * math.sin(r), cy - 118 * math.cos(r)
        s.zone(round(zx - 22), round(zy - 22), 44, 44, 'Направление ' + DNAME[a])
    return s
QT = '23. Повороты на месте выполняются по командам: "Напра-ВО", "Пол-оборота напра-ВО", "Нале-ВО", "Пол-оборота нале-ВО", "Кру-ГОМ".\nПовороты кругом (на 1/2 круга), налево (на 1/4 круга), пол-оборота налево (на 1/8 круга) производятся в сторону левой руки'
MATT = 'Схема: военнослужащий, вид сверху. Уголок на кружке показывает, куда он обращён лицом сейчас. Серые стрелки — возможные направления.'
def turn_q(id, base, d, face, cmds, text, delta):
    s = turn_svg(face); res = (face + delta) % 360
    add(id=id, type='hotspot', base=base, difficulty=d, source_doc='su', source_ref='СУ, п. 23', topic='sch-su-turn', quote=QT, text=text, material=MATT,
        media=H(s, 'Военнослужащий, вид сверху, и восемь стрелок-направлений вокруг него.'), zones=s.hz(correct_idx=[DIRS.index(res)]),
        explanation=f'{cmds}: поворот на {abs(delta) if abs(delta) <= 180 else 360 - abs(delta)}° {"влево" if delta < 0 else "вправо" if delta not in (180, -180) else ""}. Военнослужащий окажется обращён {DNAME[res]}.'.replace('  ', ' ').replace(' .', '.'))
turn_q('sch-su-13', 'simple', 1, 0, '«Нале-ВО»', 'Военнослужащий выполнил команду «Нале-ВО». Куда он теперь обращён лицом?', -90)
