    s = Svg(120, 120); s.add('<circle cx="60" cy="60" r="50" fill="none" stroke="#ccc" stroke-width="1"/>'); s.soldier(60, 60, face, r=18); r = math.radians(face); s.arrow(60 + 22 * math.sin(r), 60 - 22 * math.cos(r), round(60 + 46 * math.sin(r), 1), round(60 - 46 * math.cos(r), 1), '#b0413e', 3, 9); return {'svg': s.svg(), 'alt': 'Военнослужащий, вид сверху'}
