def posts(data):
    s = Svg(480, 300)
    for i, (name, n) in enumerate(data):
        cx, cy = i % 3, i // 3; x, y = 10 + cx * 157, 10 + cy * 145
        s.rect(x, y, 147, 135, '#ebe5d3', '#555', 2, 6); s.text(x + 73, y + 26, name, 13, bold=True)
        for k in range(n):
            px = x + 22 + (k % 5) * 26; py = y + 62 + (k // 5) * 34; s.soldier(px, py, 0, r=10)
    for i, (name, n) in enumerate(data):
        cx, cy = i % 3, i // 3; s.zone(10 + cx * 157, 10 + cy * 145, 147, 135, f'{name}: {n} постовых')
    return s
