# ======================= КоАП: дорожные ситуации =======================
def hroad(s, y0=70, y1=190, walk=True, center='dash'):
    if walk: s.rect(0, y0 - 30, s.W, 30, WALK, 'none', 0); s.rect(0, y1, s.W, 30, WALK, 'none', 0)
    s.rect(0, y0, s.W, y1 - y0, ROAD, 'none', 0)
    m = (y0 + y1) // 2
    s.line(0, m, s.W, m, '#fff', 3, '18 12' if center == 'dash' else None)
    s.line(0, y0, s.W, y0, '#777', 2); s.line(0, y1, s.W, y1, '#777', 2)
    return m
def zebra(s, x, y0, y1, w=40):
    for yy in range(y0 + 4, y1 - 4, 14): s.rect(x, yy, w, 8, '#fff', 'none', 0)
def czone(s, x, y, horiz, label, pad=6):
    w, h = (40, 22) if horiz else (22, 40)
    s.zone(x - w / 2 - pad, y - h / 2 - pad, w + 2 * pad, h + 2 * pad, label)
def dim(s, x1, x2, y, t):
    s.line(x1, y, x2, y, '#222', 1.5); s.line(x1, y - 5, x1, y + 5, '#222', 1.5); s.line(x2, y - 5, x2, y + 5, '#222', 1.5); s.text((x1 + x2) / 2, y - 6, t, 12)

