MOVE = ' Синяя стрелка — автомобиль движется в эту сторону; автомобиль без стрелки стоит.'
def mv(s, x, y, ang, ln=34, back=False):
    r = math.radians(ang); sx, sy = math.sin(r), -math.cos(r)
    if back: sx, sy = -sx, -sy
    a = (x + sx * 24, y + sy * 24); b = (x + sx * (24 + ln), y + sy * (24 + ln))
    s.arrow(round(a[0], 1), round(a[1], 1), round(b[0], 1), round(b[1], 1), '#1f4fd1', 3, 9)
def vroad(s, x0, x1, center=None, dash=True, lanes=()):
    s.rect(x0, 0, x1 - x0, s.H, ROAD, 'none', 0); s.line(x0, 0, x0, s.H, '#777', 2); s.line(x1, 0, x1, s.H, '#777', 2)
    if center: s.line(center, 0, center, s.H, '#fff', 3, '18 12' if dash else None)
    for x in lanes: s.line(x, 0, x, s.H, '#fff', 2, '14 12')

